@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700&family=Fraunces:opsz,wght@9..144,500;9..144,600;9..144,700&display=swap');
:root{--ink:#243a32;--muted:#83958c;--forest:#315e4b;--leaf:#83a76b;--cream:#f6f3e8;--line:#e6e5d9;--gold:#e4b756;--paper:#fffefa}*{box-sizing:border-box}body{margin:0;background:#f1f0e7;color:var(--ink);font-family:'DM Sans',sans-serif;min-height:100vh;background-image:radial-gradient(#d7dfcd 0.7px,transparent 0.7px);background-size:16px 16px}.shell{max-width:1260px;margin:0 auto;padding:0 28px}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #dfe3d7}.brand{display:flex;align-items:center;gap:10px;text-decoration:none;color:#284338;font:700 13px 'DM Mono',monospace;letter-spacing:1.35px}.brand b{color:#7c9d69}.brand-mark{background:#e8eddc;color:#75915e;border-radius:10px;width:32px;height:32px;display:grid;place-items:center;font-size:20px}.top-note{font:11px 'DM Mono',monospace;color:#718278;letter-spacing:.3px}.sun-dot{display:inline-block;width:7px;height:7px;background:#e6b851;border-radius:50%;margin-right:8px;box-shadow:0 0 0 4px #f4e9c7}.icon-button{border:1px solid #dfe3d7;background:#f8f8ef;color:#718278;border-radius:50%;height:34px;width:34px;font-size:15px;cursor:pointer}.game-layout{display:grid;grid-template-columns:minmax(0,1fr) 294px;gap:24px;padding-top:24px}.world-column{min-width:0}.world-frame{background:#fffefa;border:1px solid #e3e3d8;border-radius:13px;padding:13px;box-shadow:0 8px 24px #293e2210}.world-topline{height:30px;display:flex;align-items:flex-start;justify-content:space-between;padding:1px 5px 0}.location,.weather{font:10px 'DM Mono',monospace;letter-spacing:1px;color:#698074}.location i{display:inline-block;width:6px;height:6px;background:#8aa86d;border-radius:50%;margin:0 7px 1px 0}.weather{color:#9a9d8b}.weather span{color:#dbac4c;font-size:13px;margin-right:4px}.canvas-wrap{position:relative;overflow:hidden;border-radius:8px;background:#8eb17c;box-shadow:inset 0 0 0 1px #38533b55}canvas{display:block;width:100%;height:auto;image-rendering:pixelated;image-rendering:crisp-edges}.world-footer{display:flex;gap:20px;align-items:center;height:39px;padding:0 4px 0 5px;color:#849087;font:10px 'DM Mono',monospace}.world-footer kbd,.item kbd{font:9px 'DM Mono',monospace;background:#eff0e6;border:1px solid #e3e4d8;border-radius:4px;padding:3px 5px;color:#63776a;margin-right:4px}.footer-tip{margin-left:auto;color:#a0a58f;font:italic 11px 'Fraunces',serif}.sidebar{display:flex;flex-direction:column;gap:12px}.profile-card{background:#315c49;color:#f6f4e7;border-radius:11px;padding:16px 17px 14px;box-shadow:0 5px 14px #253e3017}.profile-top{display:flex;align-items:center;gap:10px}.avatar{height:38px;width:38px;border-radius:50%;display:grid;place-items:center;background:#e5e9d4;color:#557254;font-size:21px;border:2px solid #a9bf91}.player-label{font:9px 'DM Mono',monospace;color:#b9c9ad;letter-spacing:1px}.player-name{font:600 16px 'Fraunces',serif;color:#fff}.player-name span{font:11px 'DM Sans';color:#b4c5a5}.day-pill{margin-left:auto;color:#c4d2b6;border:1px solid #78917a;border-radius:20px;padding:5px 8px;font:9px 'DM Mono',monospace;letter-spacing:.5px}.day-pill b{color:#f3dc98;font-size:11px;margin-left:3px}.energy-label{display:flex;justify-content:space-between;color:#c5d3b8;font:9px 'DM Mono',monospace;letter-spacing:.55px;margin-top:16px}.energy-track,.hp-track{height:5px;background:#527460;border-radius:8px;overflow:hidden;margin-top:7px}.energy-track span{height:100%;display:block;background:#e4c96e;width:100%;border-radius:8px;transition:width .3s}.weather-note{margin-top:14px;padding-top:11px;border-top:1px solid #547461;display:flex;gap:9px;align-items:center}.weather-note>span{font-size:20px;color:#edce71}.weather-note b{font:600 11px 'DM Sans';display:block}.weather-note small{font-size:10px;color:#bdcbb6}.panel{background:#fffefa;border:1px solid #e5e5da;border-radius:10px;padding:13px 15px;box-shadow:0 3px 10px #293e2208}.panel-heading{display:flex;justify-content:space-between;align-items:center;color:#71877a;font:10px 'DM Mono',monospace;letter-spacing:.8px}.quiet{color:#b6b9aa;font-size:9px}.quest-content{display:flex;gap:11px;margin-top:13px;align-items:flex-start}.quest-icon{width:30px;height:30px;background:#f0f2e7;border-radius:8px;display:grid;place-items:center;color:#799365;font-size:17px}.quest-content b{font:600 12px 'Fraunces',serif}.quest-content p{margin:3px 0 0;color:#89948a;font-size:10px;line-height:1.45}.quest-progress{height:4px;border-radius:4px;background:#eff0e8;margin:13px 0 6px}.quest-progress span{display:block;background:#91aa73;height:100%;width:0;border-radius:4px;transition:width .4s}.quest-foot{font:9px 'DM Mono',monospace;color:#969f91}.party-list{margin-top:9px}.buddy-row{display:flex;align-items:center;gap:9px;padding:7px 0;border-top:1px solid #f0f0e8}.buddy-avatar{height:31px;width:31px;display:grid;place-items:center;border-radius:9px;background:#edf1e4;font-size:17px}.buddy-info{flex:1}.buddy-info b{font:600 11px 'Fraunces',serif;display:block}.buddy-info small{color:#93a095;font-size:9px}.buddy-hp{font:9px 'DM Mono',monospace;color:#77956e}.empty-buddy{font-size:10px;color:#9da79b;text-align:center;padding:13px 0}.small-link{border:0;background:none;color:#77906f;font:10px 'DM Sans';padding:7px 0 0;cursor:pointer}.small-link span{color:#adb3a7;margin-left:4px;font-size:9px}.inventory-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px 5px;margin-top:12px}.item{display:flex;align-items:center;gap:6px;position:relative;min-width:0}.item-icon{width:27px;height:27px;border-radius:8px;display:grid;place-items:center;font-size:15px;background:#f2f0e4;color:#9ca866}.water-icon{background:#e8f1ef;color:#76a9a4}.charm-icon{background:#f4ece2;color:#c79265}.coin-icon{background:#f7f0d9;color:#c7a248}.item b{font:600 12px 'DM Mono',monospace;display:block}.item small{font-size:9px;color:#8f9b90;white-space:nowrap}.item kbd{position:absolute;right:0;top:3px;font-size:8px;padding:2px 4px;margin:0}.side-hint{display:flex;align-items:flex-start;gap:9px;padding:4px 4px;color:#7e8f77}.side-hint>span{font-size:20px;color:#9bae7d}.side-hint b{font:600 11px 'Fraunces',serif;color:#506d55}.side-hint p{font:italic 11px 'Fraunces',serif;color:#8e9b86;margin:3px 0 0;line-height:1.35}.sleep-button{margin-top:auto;position:relative;width:100%;border:1px solid #dfe3d7;border-radius:9px;background:#f9f8ef;color:#66795f;text-align:left;padding:10px 12px 9px 39px;font:600 11px 'DM Sans';cursor:pointer}.sleep-button>span{position:absolute;left:13px;top:10px;font-size:17px;color:#b59e64}.sleep-button small{display:block;color:#a1a99d;font-size:9px;font-weight:400;margin-top:2px}.sleep-button:hover{background:#f0f2e6;border-color:#cdd7c1}.site-footer{height:45px;display:flex;align-items:center;justify-content:space-between;color:#a0a89a;font:9px 'DM Mono',monospace;letter-spacing:.4px}.site-footer span:last-child{color:#99a18f}.toast{position:absolute;bottom:15px;left:50%;transform:translate(-50%,10px);opacity:0;background:#254437eF;color:#f7f3e3;padding:9px 14px;border:1px solid #ffffff3b;border-radius:20px;font:11px 'DM Sans';pointer-events:none;transition:all .22s;white-space:nowrap;z-index:2}.toast.show{opacity:1;transform:translate(-50%,0)}.starter-screen,.battle-screen{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:center;background:#17352cc9;backdrop-filter:blur(3px)}.starter-card{background:#fcfbf2;border:1px solid #e3e4d5;border-radius:14px;padding:25px 28px 18px;width:min(92%,510px);text-align:center;box-shadow:0 20px 60px #10281d60}.starter-eyebrow{font:9px 'DM Mono',monospace;letter-spacing:1.6px;color:#849c72}.starter-card h1{font:600 30px/1.1 'Fraunces',serif;color:#294a3b;margin:11px 0 8px}.starter-card h1 em{color:#88a16f;font-weight:500}.starter-card>p{font-size:11px;line-height:1.55;color:#7f8e80;max-width:330px;margin:0 auto}.starter-options{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:19px}.starter-choice{background:#f4f4e9;border:1px solid #e6e8d9;border-radius:10px;padding:10px 5px 9px;color:#354b3c;cursor:pointer;transition:transform .2s,border .2s}.starter-choice:hover{transform:translateY(-3px);border-color:#9bb283}.starter-creature{display:grid;place-items:center;margin:auto auto 6px;width:45px;height:45px;border-radius:14px;font-size:27px}.sprig{color:#6b9a67;background:#e6efdc}.bubble{color:#69a5a5;background:#e1f0ec}.ember{color:#d6905a;background:#f5e8d8}.starter-choice b{display:block;font:600 12px 'Fraunces',serif}.starter-choice small{display:block;color:#89958a;font-size:9px;margin-top:3px}.starter-foot{margin-top:15px;color:#a2a796;font:italic 10px 'Fraunces',serif}.starter-foot span{color:#dab758;margin-left:3px}.hidden{display:none!important}.battle-screen{display:block;padding:18px 22px;background:#14362ccc}.battle-heading{display:flex;justify-content:center;align-items:center;gap:8px;color:#e3e1bf;font:10px 'DM Mono',monospace;letter-spacing:1.8px}.battle-sparkle{color:#ead37f;font-size:18px}.battle-arena{display:flex;align-items:center;justify-content:center;gap:26px;margin:12px auto 8px;max-width:420px}.wild-card,.buddy-card{width:135px;text-align:center;color:#fff}.wild-art,.buddy-art{height:58px;width:58px;border-radius:20px;margin:0 auto 4px;display:grid;place-items:center;font-size:38px;background:#dfebcb;color:#78a365;text-shadow:0 2px #fff8;box-shadow:0 5px 15px #101f2550}.buddy-art{background:#d8ece6;color:#63a7a5}.wild-name,.buddy-name{font:600 13px 'Fraunces',serif}.hp-track{height:6px;margin:5px auto;width:100px;background:#ffffff42}.hp-track span{display:block;height:100%;width:100%;border-radius:8px;background:#b9d47e;transition:width .3s}.battle-card small{font:8px 'DM Mono';color:#d1dbc9}.wild-card small,.buddy-card small{font:8px 'DM Mono',monospace;color:#d1dbc9}.battle-vs{color:#e4ce81;font-size:18px}.battle-message{min-height:27px;text-align:center;color:#f6f0d8;font:italic 13px 'Fraunces',serif;margin:3px 0 10px}.battle-actions{display:flex;justify-content:center;gap:7px}.battle-btn{width:126px;text-align:left;border:1px solid #ffffff4c;background:#f6f4e6;border-radius:8px;padding:7px 8px;color:#345342;cursor:pointer;font:10px 'DM Sans';box-shadow:0 3px 9px #1115}.battle-btn.primary{background:#dce9c7}.battle-btn.capture{background:#f3e6cf}.battle-btn.flee{background:#eceee4}.battle-btn>span{font-weight:700;font-size:9px}.battle-btn>small{display:block;color:#879281;font-size:8px;margin:3px 0 0 18px}.battle-btn:hover{transform:translateY(-2px)}.battle-continue{display:block;margin:8px auto 0;border:0;border-radius:20px;background:#e6d58f;color:#3e533d;padding:7px 18px;font:600 10px 'DM Sans';cursor:pointer}.mobile-controls{display:none}
@media(max-width:900px){.shell{padding:0 18px}.game-layout{grid-template-columns:minmax(0,1fr) 260px;gap:15px}.sidebar{gap:9px}.world-footer{gap:9px;font-size:9px}.footer-tip{display:none}.panel{padding:11px 12px}.profile-card{padding:14px}}
@media(max-width:680px){.shell{padding:0 10px}.topbar{height:56px}.top-note{display:none}.game-layout{display:flex;flex-direction:column;padding-top:12px;gap:12px}.world-frame{padding:7px;border-radius:10px}.world-topline{height:24px;padding:0 3px}.location,.weather{font-size:8px}.world-footer{height:31px;justify-content:space-around;gap:3px;font-size:8px}.world-footer kbd{font-size:7px;padding:2px 3px}.sidebar{display:grid;grid-template-columns:1fr 1fr;gap:8px}.profile-card,.quest-panel,.party-panel,.bag-panel{min-width:0}.profile-card{grid-column:span 2}.profile-top{gap:8px}.side-hint{display:none}.sleep-button{grid-column:span 2;margin:0;padding:9px 12px 8px 39px}.starter-card{padding:20px 13px 13px}.starter-card h1{font-size:25px}.starter-card>p{font-size:10px}.starter-options{gap:5px;margin-top:13px}.starter-choice{padding:8px 2px}.starter-creature{height:38px;width:38px;font-size:24px}.starter-choice b{font-size:10px}.starter-choice small{font-size:8px}.starter-foot{font-size:9px;margin-top:11px}.battle-screen{padding:12px 8px}.battle-arena{gap:6px;margin:8px auto}.wild-card,.buddy-card{width:110px}.battle-btn{width:31%;padding:7px 5px}.battle-btn>span{font-size:8px}.battle-btn>small{font-size:7px;margin-left:15px}.mobile-controls{display:flex;align-items:center;justify-content:space-between;padding:5px 14px 0}.dpad{display:grid;grid-template-columns:repeat(3,38px);grid-template-rows:repeat(2,34px);gap:3px}.dpad button{border:1px solid #dce2d3;background:#fbfaf1;color:#587357;border-radius:8px;font-size:13px;touch-action:none}.dpad button[data-move=up]{grid-column:2}.dpad button[data-move=left]{grid-column:1;grid-row:2}.dpad button[data-move=down]{grid-column:2;grid-row:2}.dpad button[data-move=right]{grid-column:3;grid-row:2}.touch-action{height:52px;width:52px;border:1px solid #dce2d3;border-radius:50%;background:#315c49;color:#f7efcc;font-size:17px;display:flex;flex-direction:column;align-items:center;justify-content:center;touch-action:none}.touch-action span{font:8px 'DM Mono';letter-spacing:.5px}.site-footer{font-size:8px;height:35px}}
@media(max-width:380px){.world-footer span:nth-child(3){display:none}.sidebar{grid-template-columns:1fr}.profile-card,.sleep-button{grid-column:auto}.quest-panel,.party-panel,.bag-panel{grid-column:auto}.starter-card h1{font-size:22px}}

(() => {
  const canvas = document.getElementById('game');
  const ctx = canvas.getContext('2d');
  ctx.imageSmoothingEnabled = false;
  const TILE = 32, W = 24, H = 16;
  const creatures = {
    spriglet: { name:'Spriglet', type:'Leaf', icon:'✿', color:'#78a56a', hp:26, attack:7 },
    bubbun: { name:'Bubbun', type:'Water', icon:'◉', color:'#69a9aa', hp:28, attack:6 },
    cindercub: { name:'Cindercub', type:'Ember', icon:'☼', color:'#d99559', hp:24, attack:8 },
    mossling: { name:'Mossling', type:'Leaf', icon:'❋', color:'#83a65e', hp:18, attack:5 },
    pebblit: { name:'Pebblit', type:'Earth', icon:'⬟', color:'#ba9875', hp:22, attack:6 },
    dewfin: { name:'Dewfin', type:'Water', icon:'❧', color:'#72b3b0', hp:20, attack:5 },
    puffern: { name:'Puffern', type:'Air', icon:'✿', color:'#c4a4b8', hp:16, attack:4 }
  };
  const defaultState = () => ({ day:1, x:10, y:13, direction:'down', energy:100, coins:24, seeds:5, charms:3, starter:null, party:[], plots:Array.from({length:6},()=>({crop:null,planted:0,watered:false})), plantedAny:false, caughtAny:false });
  let state = defaultState();
  try { const s=JSON.parse(localStorage.getItem('mosslight-save')); if(s&&s.starter){state={...defaultState(),...s}; if(!Array.isArray(state.plots)||state.plots.length!==6)state.plots=defaultState().plots;} } catch(e){}
  let keys={}, lastMove=0, toastTimer, battle=null, soundOn=false;
  const plots=[{x:8,y:10},{x:9,y:10},{x:10,y:10},{x:8,y:11},{x:9,y:11},{x:10,y:11}];
  const tallGrass=[]; for(let y=4;y<=8;y++)for(let x=14;x<=20;x++) if(!((x===14&&y===4)||(x===20&&y===8)))tallGrass.push(`${x},${y}`);
  const solid=new Set();
  for(let y=2;y<=5;y++)for(let x=3;x<=7;x++)solid.add(`${x},${y}`);
  for(let y=3;y<=5;y++)for(let x=16;x<=18;x++)solid.add(`${x},${y}`); // pond
  const $=id=>document.getElementById(id);
  const save=()=>{try{localStorage.setItem('mosslight-save',JSON.stringify(state));}catch(e){} updateUI();};
  function toast(text){const el=$('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
  function updateUI(){
    $('dayNumber').textContent=state.day; $('seasonDay').textContent=state.day; $('footerYear').textContent=String(state.day).padStart(2,'0');
    $('energyText').textContent=`${state.energy} / 100`; $('energyBar').style.width=`${state.energy}%`;
    $('seedCount').textContent=state.seeds; $('charmCount').textContent=state.charms; $('coinCount').textContent=state.coins;
    $('partyCount').textContent=`${String(state.party.length).padStart(2,'0')} / 06`;
    $('partyList').innerHTML=state.party.length?state.party.map((c,i)=>`<div class="buddy-row"><div class="buddy-avatar" style="color:${c.color}">${c.icon}</div><div class="buddy-info"><b>${c.name}${i===0?' · companion':''}</b><small>${c.type} spirit</small></div><div class="buddy-hp">${c.currentHp||c.hp} HP</div></div>`).join(''):'<div class="empty-buddy">Choose a companion to begin ✦</div>';
    const progress=(state.plantedAny?1:0)+(state.caughtAny?1:0); $('questBar').style.width=`${progress*50}%`; $('questText').textContent=`${progress} of 2 happy beginnings`;
    $('starterScreen').classList.toggle('hidden',!!state.starter);
  }
  function roundRect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);if(fill){ctx.fillStyle=fill;ctx.fill()}if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
  function hash(x,y){return (x*37+y*91+x*y*13)%17}
  function drawTile(x,y){
    const n=hash(x,y), px=x*TILE, py=y*TILE;
    let color=n<6?'#86ad79':n<12?'#8bb17c':'#84aa75';
    ctx.fillStyle=color;ctx.fillRect(px,py,TILE,TILE);
    // soft tile variation
    if(n===0){ctx.fillStyle='#9bbd86';ctx.fillRect(px+4,py+7,2,2);ctx.fillRect(px+23,py+24,2,2)}
    if(n===4){ctx.fillStyle='#729b6c';ctx.fillRect(px+10,py+20,2,4);ctx.fillRect(px+14,py+18,2,6)}
    // paths winding through yard
    const path=(x>=8&&x<=10&&y>=12)||(x>=8&&x<=10&&y===9)||(x>=8&&x<=9&&y===8)||(x>=5&&x<=10&&y>=6&&y<=7)||(x===10&&y>=7&&y<=9)||(x>=10&&x<=14&&y===8)||(x>=12&&x<=13&&y>=8&&y<=12)||(x>=3&&x<=8&&y===12);
    if(path){ctx.fillStyle='#cbbd91';ctx.fillRect(px,py,TILE,TILE);ctx.fillStyle='#d5c9a1';ctx.fillRect(px+2,py+3,28,2);if(n%3===0){ctx.fillStyle='#b9aa81';ctx.fillRect(px+22,py+19,3,2)}}
    // shadowed meadow grass
    if(tallGrass.includes(`${x},${y}`)){ctx.fillStyle='#669666';ctx.fillRect(px,py,TILE,TILE);for(let i=0;i<5;i++){const gx=px+4+(i*11)%25,gy=py+13+(i*9)%13;ctx.fillStyle=i%2?'#8fbd76':'#a3c77a';ctx.beginPath();ctx.moveTo(gx-4,gy+9);ctx.lineTo(gx,gy-7-(i%3)*2);ctx.lineTo(gx+4,gy+9);ctx.fill()}ctx.fillStyle='#76a46e';ctx.fillRect(px+2,py+27,28,3)}
  }
  function flower(x,y,color){const px=x*TILE+16,py=y*TILE+17;ctx.fillStyle='#61885c';ctx.fillRect(px-1,py,2,11);ctx.fillStyle=color;for(let i=0;i<5;i++){let a=i*Math.PI*2/5;ctx.beginPath();ctx.arc(px+Math.cos(a)*4,py+Math.sin(a)*4,3,0,Math.PI*2);ctx.fill()}ctx.fillStyle='#f4d36d';ctx.fillRect(px-2,py-2,4,4)}
  function drawHouse(){const x=3*TILE,y=2*TILE;ctx.fillStyle='#536b4a';ctx.fillRect(x+4,y+29,166,105);ctx.fillStyle='#f0dfb8';ctx.fillRect(x+11,y+38,152,91);ctx.fillStyle='#b87859';ctx.beginPath();ctx.moveTo(x-3,y+42);ctx.lineTo(x+86,y-10);ctx.lineTo(x+177,y+42);ctx.closePath();ctx.fill();ctx.fillStyle='#d18c66';ctx.beginPath();ctx.moveTo(x+86,y-10);ctx.lineTo(x+177,y+42);ctx.lineTo(x+162,y+42);ctx.lineTo(x+84,y+1);ctx.closePath();ctx.fill();ctx.fillStyle='#6b5144';ctx.fillRect(x+66,y+71,33,58);ctx.fillStyle='#e7c888';ctx.fillRect(x+70,y+75,25,48);ctx.fillStyle='#8c7457';ctx.fillRect(x+88,y+100,3,3);ctx.fillStyle='#8bc1b4';ctx.fillRect(x+25,y+53,25,24);ctx.fillRect(x+117,y+53,25,24);ctx.fillStyle='#f6e8c6';ctx.fillRect(x+29,y+57,17,16);ctx.fillRect(x+121,y+57,17,16);ctx.fillStyle='#a5c6b7';ctx.fillRect(x+37,y+57,2,16);ctx.fillRect(x+29,y+64,17,2);ctx.fillRect(x+129,y+57,2,16);ctx.fillRect(x+121,y+64,17,2);ctx.fillStyle='#795b43';ctx.fillRect(x+75,y-3,23,20);ctx.fillStyle='#b87054';ctx.fillRect(x+72,y-4,29,5);ctx.fillStyle='#66845a';ctx.fillRect(x+4,y+130,167,5);}
